 "content": "from collections import Counter, deque

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Find a full-width horizontal separator.
    sep=next(r for r,row in enumerate(g) if len(set(row))==1)
    sepcolor=g[sep][0]
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    # Find the non-background, non-separator object as 4-connected components.
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if (r,c) in seen or g[r][c] in (bg,sepcolor):
                continue
            color=g[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                y,x=q.pop(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append(comp)
    comp=max(comps,key=len)
    minr=min(r for r,c in comp); maxr=max(r for r,c in comp)
    if maxr < sep:
        dr=sep-1-maxr
        markrow=minr-1
    else:
        dr=sep+1-minr
        markrow=maxr+1
    # Clear old object, move it flush against the separator, and mark the trailing row.
    for r,c in comp: g[r][c]=bg
    moved=[(r+dr,c) for r,c in comp]
    for r,c in moved: g[r][c]=grid[minr+(r-(minr+dr))][c] if False else next(grid[y][x] for y,x in comp if x==c and y+dr==r)
    if 0<=markrow<h:
        g[markrow]=[8]*w
    return g
